"""Download endpoints for CSV/XLSX exports generated by the background worker."""
from __future__ import annotations

from datetime import datetime, timezone
from pathlib import Path

from fastapi import APIRouter, Depends, HTTPException, Query
from fastapi.responses import FileResponse

from app.auth import CurrentUser, get_current_user
from app.settings import settings

router = APIRouter(prefix="/exports", tags=["exports"])

EXPORT_ROOT = Path(settings.export_root).resolve()
MEDIA_TYPES = {
    ".csv": "text/csv",
    ".xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
}


def _user_export_dir(user: CurrentUser) -> Path:
    return (EXPORT_ROOT / str(user.id)).resolve()


@router.get("")
def list_exports(user: CurrentUser = Depends(get_current_user)):
    """List finished exports for the caller."""
    user_dir = _user_export_dir(user)
    if not user_dir.is_dir():
        return []
    return [
        {
            "name": entry.name,
            "size": entry.stat().st_size,
            "created_at": datetime.fromtimestamp(entry.stat().st_mtime, tz=timezone.utc),
        }
        for entry in sorted(user_dir.iterdir())
        if entry.is_file()
    ]


@router.get("/download")
def download_export(
    name: str = Query(..., min_length=1),
    user: CurrentUser = Depends(get_current_user),
):
    """Stream one of the caller's finished exports."""
    user_dir = _user_export_dir(user)
    export_path = (user_dir / name).resolve()
    if not export_path.is_relative_to(user_dir) or not export_path.is_file():
        raise HTTPException(status_code=404, detail="Export not found")
    return FileResponse(
        export_path,
        media_type=MEDIA_TYPES.get(export_path.suffix.lower(), "application/octet-stream"),
        filename=export_path.name,
    )
